package org.example.stock.migration;

import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** Ajout du journal, sans recalculer ni réinitialiser les stocks et caisses existants. */
public final class InventaireMigration {
    static final String TABLE="mouvement_stock", VERROU="stock_inventaire_migration";
    private InventaireMigration() {}
    public static void main(String[] args) {
        BoutiquesMigration.masquerLogsJdbc();
        if(args.length!=1||!Set.of("--check","--apply").contains(args[0]))throw new IllegalArgumentException("Utiliser --check ou --apply");
        try {
            Properties config=new Properties();try(var r=Files.newBufferedReader(Path.of("src/main/resources/application.properties"))){config.load(r);}
            String url=AccountEmailMigration.resolve(config.getProperty("spring.datasource.url")).replace("createDatabaseIfNotExist=true","createDatabaseIfNotExist=false");
            boolean appliquer=args[0].equals("--apply");
            if(appliquer){BoutiquesMigration.verifierCibleSauvegarde(url);String dossier=System.getenv("INVENTAIRE_BACKUP_DIR");if(dossier==null||dossier.isBlank())throw new IllegalStateException("Définir INVENTAIRE_BACKUP_DIR après une sauvegarde SQL complète.");BoutiquesMigration.verifierSauvegarde(dossier);}
            try(var c=DriverManager.getConnection(url,AccountEmailMigration.resolve(config.getProperty("spring.datasource.username")),AccountEmailMigration.resolve(config.getProperty("spring.datasource.password")))){migrer(c,appliquer);}
        }catch(Exception e){System.err.println("Migration inventaire interrompue : "+(e instanceof IllegalStateException?e.getMessage():"Opération SQL impossible ; aucune valeur privée publiée."));System.exit(1);}
    }
    static void migrer(Connection c,boolean appliquer)throws SQLException {
        boolean maria=c.getMetaData().getDatabaseProductName().equals("MariaDB"),verrou=false;
        if(!maria&&!c.getMetaData().getDatabaseProductName().equals("H2"))throw new IllegalStateException("MariaDB ou H2 requis");
        if(!c.getAutoCommit())throw new IllegalStateException("Connexion dédiée sans transaction requise");
        try {
            c.setReadOnly(!appliquer);
            if(appliquer&&maria){if(BoutiquesMigration.compter(c,"SELECT GET_LOCK('"+VERROU+"',0)")!=1)throw new IllegalStateException("Une migration inventaire est déjà en cours.");verrou=true;}
            if(!BoutiquesMigration.tables(c).containsKey(AbonnementMigration.TABLE))throw new IllegalStateException("La migration des abonnements doit être terminée.");
            AbonnementMigration.migrer(c,false);c.setReadOnly(!appliquer);
            var avant=photographie(c);
            if(!BoutiquesMigration.tables(c).containsKey(TABLE)) {
                if(!appliquer){System.out.println("Inventaire vérifié en lecture seule ; aucun stock ni solde initial ajouté.");return;}
                creer(c,maria);
            }
            verifier(c,maria);
            if(!avant.equals(photographie(c)))throw new IllegalStateException("Des données ont changé : conserver l’application arrêtée et examiner la sauvegarde.");
            System.out.println("Inventaire conforme ; seize tables précédentes conservées, aucun mouvement ni solde initial inventé.");
        }finally{if(verrou)BoutiquesMigration.compter(c,"SELECT RELEASE_LOCK('"+VERROU+"')");}
    }
    private static void creer(Connection c,boolean maria)throws SQLException {
        BoutiquesMigration.executer(c,"CREATE TABLE mouvement_stock (id BIGINT NOT NULL "+(maria?"AUTO_INCREMENT":"GENERATED BY DEFAULT AS IDENTITY")+" PRIMARY KEY,boutique_id BIGINT NOT NULL,produit_id BIGINT NOT NULL,acteur_id BIGINT NOT NULL,acteur_nom VARCHAR(255) NOT NULL,type VARCHAR(16) NOT NULL,cree_le "+(maria?"DATETIME(6)":"TIMESTAMP(6)")+" NOT NULL,quantite_avant BIGINT NOT NULL,quantite_apres BIGINT NOT NULL,cout_unitaire DECIMAL(17,2) NULL,motif VARCHAR(500) NOT NULL,CONSTRAINT fk_mouvement_stock_boutique FOREIGN KEY(boutique_id) REFERENCES boutique(id),CONSTRAINT fk_mouvement_stock_produit FOREIGN KEY(produit_id) REFERENCES produit(id))"+(maria?" ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci":""));
        BoutiquesMigration.executer(c,"CREATE INDEX idx_mouvement_stock_produit_date ON mouvement_stock(boutique_id,produit_id,cree_le,id)");
    }
    private static void verifier(Connection c,boolean maria)throws SQLException {
        var cols=InscriptionEssaiMigration.colonnes(c,TABLE);
        Set<String> attendues=Set.of("id","boutique_id","produit_id","acteur_id","acteur_nom","type","cree_le","quantite_avant","quantite_apres","cout_unitaire","motif");
        if(!cols.keySet().equals(attendues))invalide();
        for(var nom:attendues)if(cols.get(nom).nullable()!=(nom.equals("cout_unitaire")?DatabaseMetaData.columnNullable:DatabaseMetaData.columnNoNulls))invalide();
        for(var nom:List.of("id","boutique_id","produit_id","acteur_id","quantite_avant","quantite_apres"))if(cols.get(nom).type()!=Types.BIGINT)invalide();
        for(var e:Map.of("acteur_nom",255,"type",16,"motif",500).entrySet())if(cols.get(e.getKey()).type()!=Types.VARCHAR||cols.get(e.getKey()).taille()!=e.getValue())invalide();
        var cout=cols.get("cout_unitaire");if((cout.type()!=Types.DECIMAL&&cout.type()!=Types.NUMERIC)||cout.taille()!=17||cout.decimales()!=2)invalide();
        if(!cols.get("id").autoIncrement()||cols.get("cree_le").type()!=Types.TIMESTAMP||(!maria&&cols.get("cree_le").decimales()!=6))invalide();
        String physique=BoutiquesMigration.tables(c).get(TABLE);
        try(var r=c.getMetaData().getPrimaryKeys(c.getCatalog(),c.getSchema(),physique)){if(!r.next()||!r.getString("COLUMN_NAME").equalsIgnoreCase("id")||r.next())invalide();}
        Set<String> fks=new HashSet<>();try(var r=c.getMetaData().getImportedKeys(c.getCatalog(),c.getSchema(),physique)){while(r.next()){if(!r.getString("PKCOLUMN_NAME").equalsIgnoreCase("id")||r.getShort("KEY_SEQ")!=1||r.getShort("DELETE_RULE")==DatabaseMetaData.importedKeyCascade)invalide();fks.add(r.getString("FKCOLUMN_NAME").toLowerCase(Locale.ROOT)+":"+r.getString("PKTABLE_NAME").toLowerCase(Locale.ROOT));}}
        if(!fks.equals(Set.of("boutique_id:boutique","produit_id:produit")))invalide();
        Map<Integer,String> index=new TreeMap<>();try(var r=c.getMetaData().getIndexInfo(c.getCatalog(),c.getSchema(),physique,false,false)){while(r.next())if("idx_mouvement_stock_produit_date".equalsIgnoreCase(r.getString("INDEX_NAME")))index.put((int)r.getShort("ORDINAL_POSITION"),r.getString("COLUMN_NAME").toLowerCase(Locale.ROOT));}
        if(!new ArrayList<>(index.values()).equals(List.of("boutique_id","produit_id","cree_le","id")))invalide();
        if(maria){try(var s=c.prepareStatement("SELECT engine,table_collation FROM information_schema.tables WHERE table_schema=? AND table_name=?")){s.setString(1,c.getCatalog());s.setString(2,physique);try(var r=s.executeQuery()){if(!r.next()||!"InnoDB".equalsIgnoreCase(r.getString(1))||!"utf8mb4_unicode_ci".equalsIgnoreCase(r.getString(2)))invalide();}}try(var s=c.prepareStatement("SELECT datetime_precision FROM information_schema.columns WHERE table_schema=? AND table_name=? AND column_name='cree_le' AND data_type='datetime'")){s.setString(1,c.getCatalog());s.setString(2,physique);try(var r=s.executeQuery()){if(!r.next()||r.getInt(1)!=6)invalide();}}}
        if(BoutiquesMigration.compter(c,"SELECT COUNT(*) FROM mouvement_stock m JOIN produit p ON p.id=m.produit_id WHERE m.boutique_id<>p.boutique_id OR m.quantite_avant<0 OR m.quantite_apres<0 OR m.acteur_id<=0 OR TRIM(m.acteur_nom)='' OR TRIM(m.motif)='' OR m.type NOT IN ('INITIAL','AJUSTEMENT') OR (m.type='INITIAL' AND (m.quantite_avant<>0 OR m.quantite_apres<=0 OR m.cout_unitaire IS NULL OR m.cout_unitaire<0)) OR (m.type='AJUSTEMENT' AND (m.quantite_avant=m.quantite_apres OR m.cout_unitaire IS NOT NULL))")!=0)invalide();
        if(BoutiquesMigration.compter(c,"SELECT COUNT(*) FROM (SELECT produit_id FROM mouvement_stock WHERE type='INITIAL' GROUP BY produit_id HAVING COUNT(*)>1) doublons")!=0)invalide();
    }
    private static void invalide(){throw new IllegalStateException("Journal d’inventaire non conforme ; aucune réparation automatique.");}
    static Map<String,List<List<Object>>> photographie(Connection c)throws SQLException {
        Map<String,List<List<Object>>> resultat=new TreeMap<>();
        for(var table:BoutiquesMigration.tables(c).entrySet()) {
            if(table.getKey().equals(TABLE))continue;
            String ordre=switch(table.getKey()){case "operation_creation"->"jeton";case "inscription_boutique"->"email";case "reinitialisation_mot_de_passe"->"utilisateur_id";default->"id";};
            String nom=table.getValue();if(!nom.matches("[A-Za-z0-9_]+"))throw new IllegalStateException("Nom de table inattendu");
            List<List<Object>> rows=new ArrayList<>();try(var s=c.createStatement();var r=s.executeQuery("SELECT * FROM "+nom+" ORDER BY "+ordre)){while(r.next()){List<Object> row=new ArrayList<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)row.add(r.getObject(i));rows.add(row);}}
            resultat.put(table.getKey(),rows);
        }
        return resultat;
    }
}
